import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    使用自定义AscendC核实现深度可分离2D卷积：先depthwise，再pointwise(1x1)。
    仅支持float, ND格式；stride=1, dilation=1；padding由kernel size推导为same。
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        # 仍复用PyTorch的权重管理与初始化
        self.depthwise = torch.nn.Conv2d(in_channels, in_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)
        self.pointwise = torch.nn.Conv2d(in_channels, out_channels, kernel_size=1, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # 直接调用自定义算子，传入权重
        return custom_ops_lib.conv_depthwise_separable_2d_custom(x, self.depthwise.weight, self.pointwise.weight)
